"""Panel copy and code patches for the Edge0-35B atlas (anchored on the engine's own text)."""

REWRITES: list[tuple[str, str]] = [
 # ---------- document chrome ----------
 ('<meta name="description" content="Offline Preact and WebGL2 architecture atlas for DeepSeek',
  '<meta name="description" content="Offline Preact and WebGL2 architecture atlas for Edge0-35B-A3B-preview: a 4-bit MLX build of Qwen3.6-35B-A3B with 30 gated-linear and 10 full-attention layers, 256 experts per layer, Recover-LoRA adapters and a prerouter head, measured against the BF16 and FP8 bases.">'),
 ("<title>DeepSeek V4.1 Flash - Tensor Atlas v4</title>",
  ' <title>Edge0 35B A3B - Tensor Atlas v4</title>'),
 ("DeepSeek Model Atlas requires JavaScript",
  '<div id="root"></div><noscript><div style="padding:40px;color:#d7e6ff;font-family:monospace">Edge0 Model Atlas requires JavaScript. Everything needed is already embedded in this file. Enable JavaScript and reload.</div></noscript>'),
 ("/* DeepSeek V4.1 Flash Atlas. Model facts from the supplied configs and",
  '/* Edge0 35B A3B Atlas. Architecture from the published config of Edge0/Edge0-35B-A3B-preview;'),
 ("DeepSeek's reference source; byte totals are schema-derived, not shard-audited. */",
  "   every byte was measured from the safetensors headers of the BF16, FP8 and int4 checkpoints. */"),
 # ---------- overview ----------
 ("ONE CHECKPOINT / ONE CONTINUOUS FORWARD PASS",
  '  <div class="intro-kicker">ONE ARCHITECTURE / THREE PUBLISHED PRECISIONS</div><h2 class="editorial">71.9 GB.<br/><em>Then a quarter of it.</em></h2><p class="lede">The same 40-layer, 256-expert MoE appears here as a BF16 teacher, an FP8 build and the 4-bit MLX checkpoint that edge0 streams from storage into under 3 GiB of RAM.</p>'),
 ("Decode execution order",
  '  <div class="decode-path" aria-label="Decode execution order"><span>Embedding</span><i>\\u2192</i><span>L00\\u2013L39<small>30 gated-linear + 10 full</small></span><i>\\u2192</i><span>Shared expert<small>always on</small></span><i>\\u2192</i><span>LoRA delta</span><i>\\u2192</i><span>Head</span></div>'),
 ("Same block pattern, different weights",
  '  <${Section} title="One stack, two block types"><p class="fine">Thirty layers are gated linear attention: a fused q/k/v projection, a gate, per-channel decay, a kernel-4 convolution and a constant-size recurrent state. Every fourth layer is full attention with a growing KV cache. <b>They interleave in one stack</b> — layers 3, 7, 11 … 39 are the full ones.</p><p class="fine">Both types carry the same feed-forward: a 256-expert bank, a router, and an always-on shared expert. The tower view shows the real order; the split view groups the first and second twenty layers for reading.</p><button class="text-link" onClick=${()=>this.setLayout(s.layout===\'tower\'?\'split\':\'tower\')}>${s.layout===\'tower\'?\'Separate the two layer ranges\':\'Merge into one numbered tower\'} <${Icon} name="arrow" size=${14}/></button><//>'),
 ("What actually changes at the boundary?",
  '  <${Section} title="What actually changes between the halves?"><p class="fine">Nothing architectural: the split is a reading aid. Both halves mix gated-linear and full-attention layers, both route 8 of 256 experts per token, and both carry a LoRA adapter set in the edge build.</p><p class="fine">What genuinely differs across the three checkpoints on this page is precision and bookkeeping: the BF16 base writes experts as fused banks, FP8 writes them per expert with per-block scale tensors, and the edge build packs each projection into U32 words with group-64 scales and biases.</p><//>'),
 ("Then why does prefill sometimes show only half?",
  '  <details class="assumptions"><summary>Why is the int4 file only a quarter of the BF16 one?</summary><p>Affine 4-bit with group size 64 stores each 2048-wide row as 512 bytes of packed weights plus a scale and a bias per group of 64. On top of that the edge build drops the vision tower entirely and keeps 80 router modules at 8 bits, so it is not a uniform 4×.</p><a href=${SOURCE_BASE} target="_blank" rel="noopener noreferrer">Read the Edge0 model card</a></details>'),
 # ---------- facts ----------
 ("<small>BACKBONE</small>",
  '  <div class="stat-grid"><div><small>PARAMETERS</small><strong>35<span>B total</span></strong></div><div><small>ACTIVE / TOKEN</small><strong>3<span>B</span></strong></div><div><small>ROUTED EXPERTS</small><strong>8<span>of 256</span></strong></div><div><small>EDGE ACTIVE RAM</small><strong>&lt;3<span>GiB</span></strong></div></div>'),
 ("The model card describes an optimized prefill",
  '  <${Note}>The three payloads on this page — 71.9036, 37.4548 and 19.6895 GB — are sums of tensor byte ranges read from the published shard headers. Parameter, memory and throughput claims come from the Edge0 model card; the alpha-adjusted benchmark table is labelled as such.<//>'),
 ("Read the architecture / click to unfold",
  '  <${Section} title="Read the architecture / click to unfold" tag="40 layers"><div class="mode-legend">${[[\'full\',\'10\',\'Full attention\'],[\'swa\',\'30\',\'Gated linear\']].map(([key,n,label])=>html`<button class="mode-key" onClick=${()=>this.select(LAYERS.find(l=>l.mode===key).id)}><i style=${{background:COL[key]}}/><b>${n}</b><span>${label}</span></button>`)}</div>'),
 ('label="Hidden width / mHC streams"',
  '   <${Fact} label="Hidden width" value="2,048"/><${Fact} label="Attention heads / head width" value="16 / 256"/><${Fact} label="Experts per layer" value="256 routed + 1 shared"/><${Fact} label="Routed experts used / token" value="8 of 256"/><${Fact} label="Full attention every" value="4th layer"/><${Fact} label="Linear attention heads" value="16 K / 32 V at 128 dims" color=${COL.full}/><p class="fine">Full attention layers are 3, 7, 11 … 39; the rest are gated linear attention with a fixed-size state. All layer numbers are zero-based.</p><//>'),
 ("Guided tour: Full, Reindex and Reuse",
  '  <button class="outline-btn full-width" onClick=${()=>this.patch({tab:\'guide\'})}>Guided tour: a linear layer, a full layer, the adapters <${Icon} name="arrow" size=${14}/></button><${Section} title="Beyond the blocks">${[[\'vision\',\'V\',\'Vision tower\',\'27 blocks · base only, absent here\',COL.vision],[\'adapters\',\'A\',\'Recover-LoRA adapters\',\'620 tensors / 42.3 MB / 40 layers\',COL.lora],[\'aligner\',\'P\',\'Prerouter heads\',\'33 layers / 138.4 MB\',COL.prerouter]].map(([id,letter,title,sub,c])=>html`<button class="feature-link" onClick=${()=>this.select(id)}><span class="feature-icon" style=${{color:c}}>${letter}</span><span><b>${title}</b><small>${sub}</small></span><${Icon} name="chevron" size=${14}/></button>`)}<//>'),
 ("What the volumes mean",
  '  <${Section} title="What the volumes mean" tag="Storage, not VRAM"><${Fact} label="Logical values in this inventory" value=${fmtP(TOTAL_P)}/><${Fact} label=${MODE_INFO[s.precision].label+\' payload\'} value=${bytes(TOTALS[s.precision],s.binary)} color=${MODE_INFO[s.precision].color}/><p class="fine">Solids use one common scale: 1 cubic world unit = 1 GB. Payloads are measured from shard headers, not derived from shapes. Active memory — the under-3-GiB claim — is a runtime quantity and is not modelled here.</p><button class="text-link" onClick=${()=>this.setView(\'storage\')}>Inspect the byte ledger <${Icon} name="arrow" size=${15}/></button><//>'),
 # ---------- layer panel ----------
 ("Decode step ${m.index+1} of 40.",
  ' ${m.mode&&html`<p class="layer-execution"><b>Block ${String(m.index).padStart(2,\'0\')} of 40.</b> ${m.mode===\'swa\'?\'Gated linear attention: constant-size state, then 8 of 256 experts plus the shared expert.\':\'Full attention: 16 query heads over 2 KV heads at head_dim 256, the only layers whose cache grows with context.\'}</p>`}'),
 ("['Main attention queries'",
  '  [\'Attention\',\'Own weights\',\'Fused q/k/v plus gate and decay in the linear layers; separate q/k/v/o in the full ones.\',TC.q,\'own\'],'),
 ("['Local SWA KV'",
  '  [\'Recurrent state\',m.mode===\'swa\'?\'Own weights\':\'Absent\',m.mode===\'swa\'?\'32 value heads × 128 × 128 keys: fixed size, whatever the prompt length.\':\'This layer keeps a KV cache instead of a recurrence.\',TC.local,m.mode===\'swa\'?\'own\':\'off\'],'),
 ("['Global main KV'",
  '  [\'KV cache\',m.mode===\'full\'?\'Own weights\':\'Absent\',m.mode===\'full\'?\'2 KV heads × 256 dims, and it grows with the context.\':\'No KV cache in the thirty gated-linear layers.\',TC.kv,m.mode===\'full\'?\'own\':\'off\'],'),
 ("['Indexer keys'",
  '  [\'Router\',\'Own weights\',\'2048 → 256 logits; the top 8 experts fire. Kept at 8-bit in the int4 build.\',TC.router,\'own\'],'),
 ("['Top-512 selection'",
  '  [\'Shared expert\',\'Own weights\',\'2048 → 512 → 2048, always on, and a LoRA target in the edge build.\',TC.shared,\'own\']'),
 ("Borrowed objects are runtime memory",
  ' <p class="fine">Nothing here is borrowed between layers. The real difference is what each layer keeps: a constant-size recurrent state, or a KV cache that grows.</p><//>`}'),
 ('title="Inside one expert"',
  ' ${isLayer&&html`<${Section} title="Inside the feed-forward" tag=${CT.num_experts+\' / TOP-\'+CT.num_experts_per_tok}><div class="expert-equation">router = Wg h            \\u2192 256 logits<br/>gate, up = W1 x, W3 x   \\u2192 512 each, per expert<br/>out = \\u03a3 top-8 softmax \\u00b7 W2 (silu(gate) \\u2299 up) + shared</div><${Fact} label="One expert / logical parameters" value=${fmtP(MOE_EXPERT_P)}/><${Fact} label="Experts stored / layer" value="256 (8 used per token)"/><${Fact} label="Expert bytes / layer" value=${bytes(sumB(m.ws.filter(w=>w.cat===\'expert\'),s.precision),s.binary)}/><p class="fine">In the BF16 base the two banks are single fused tensors with all 256 experts inside; FP8 writes them per expert and the edge build stores one packed SwitchLinear per projection. Unfolding conserves mass either way.</p><button class="outline-btn full-width" onClick=${()=>this.patch({expertView:!s.expertView,expert:null,tensor:null,hoverTensor:null})}>${s.expertView?\'Return to named tensor banks\':\'Unfold all 256 experts\'} <${Icon} name="expand" size=${14}/></button><//>`}'),
 ("${m.id[0]==='E'&&html`<${Section} title=\"From token IDs to a gated lookup\"",
  ' ${(m.id===\'adapters\'||m.id===\'aligner\')&&html`<${Section} title="The two adapters"><${Fact} label="Recover-LoRA" value="620 tensors / 42.3 MB"/><${Fact} label="LoRA targets" value="attention + shared expert, 40 layers"/><${Fact} label="Prerouter" value="99 tensors / 138.4 MB"/><${Fact} label="Prerouter coverage" value="33 layers, fc1 + fc2 + init"/><p class="fine">Neither adapter touches the routed experts. LoRA corrects the quantization error of the frozen int4 base by distillation from the FP teacher; the prerouter predicts the next layer\\u2019s routing so the expert fetch can overlap the forward pass instead of stalling it.</p><//>`}'),
 ("Images meet the language model",
  ' ${(m.id===\'vision\')&&html`<${Section} title="Images meet the language model — in the base only"><div class="expert-equation">16 \\u00d7 16 patches, temporal 2, spatial merge 2<br/>\\u2193 27 vision blocks, hidden 1,152, 16 heads<br/>\\u2193 a 4,304-wide GELU-tanh MLP per block<br/>\\u2193 merger: 4 \\u00d7 1,152 \\u2192 2,048<br/>2,048-channel visual embeddings</div><p class="fine">Twelve tensors per block, combined here into a bank marked \\u00d727 — 27 separately stored blocks, not shared weights. The edge preview ships none of them: measured across its six files, the int4 checkpoint contains no vision tensor at all.</p><//>`}'),
 ("NVFP4 only changes the explicitly targeted backbone routed experts",
  ' <${Section} title="Same weights, different payload">${Object.keys(MODE_INFO).map(mode=>{const b=sumB(m.ws,mode);return html`<div class="ledger-bar"><div><span>${MODE_INFO[mode].label}</span><b>${bytes(b,s.binary)}</b></div><span><i style=${{width:b/sumB(m.ws,\'bf16\')*100+\'%\',background:MODE_INFO[mode].color,opacity:mode===s.precision?1:.35}}/></span></div>`;})}<p class="fine">FP8 halves every linear including the experts; the edge build takes the experts to a quarter and drops the vision tower, but keeps the routers at 8-bit.</p><//></div>`;'),
 # ---------- guide ----------
 ("Follow the data.<br/><em>Read the weights.</em>",
  ' renderGuide(){return html`<div><div class="inspect-path">A READING GUIDE TO THE ANIMATION</div><h2 class="editorial">Follow the data.<br/><em>Read the weights.</em></h2><p class="lede">The solids are learned tensors. The moving lights are explanatory signals. Do not read the size of a weight as its runtime workload.</p>'),
 ("Start with a Reuse layer",
  ' <${Section} title="Start with a gated-linear layer"><p class="guide-copy">Open L00. A fused q/k/v projection feeds a kernel-4 convolution and a gated recurrence whose state is a fixed 32 × 128 × 128 block — it does not grow with the prompt. Then the feed-forward: 8 of 256 experts plus the shared expert.</p><button class="outline-btn full-width" onClick=${()=>{this.select(\'L0\');this.patch({tab:\'inspect\'});}}>Open L00: a gated-linear layer</button><//>'),
 ("Compare a Full layer",
  ' <${Section} title="Compare a full-attention layer"><p class="guide-copy">Now open L03. Sixteen query heads over just two KV heads at head_dim 256, with per-head q and k norms, and a KV cache that grows with the context. Only these ten layers pay for long prompts.</p><button class="outline-btn full-width" onClick=${()=>{this.select(\'L3\');this.patch({tab:\'inspect\'});}}>Open L03: the first full layer</button><//>'),
 ("Cross the encoder-decoder boundary",
  ' <${Section} title="Where the 8.4 GB lives"><p class="guide-copy">Open any layer and switch the inspector to Experts, or press X: 256 specialists per layer, [256, 1024, 2048] for gate_up and [256, 2048, 512] for down. Eight run per token; all 256 are stored, and at BF16 they are the bulk of the checkpoint.</p><button class="outline-btn full-width" onClick=${()=>{this.select(\'L3\');this.patch({expertView:true,tab:\'inspect\'});}}>Open L03: unfold all 256 experts</button><//>'),
 ("Same memory, a different search",
  ' <${Section} title="Then look at the two adapters"><p class="guide-copy">The edge build ships 180 MB of adapters next to a 19.7 GB checkpoint. LoRA (620 tensors, 42.3 MB) corrects the 4-bit error on attention and the shared expert; the prerouter (99 tensors, 138.4 MB, 33 layers) predicts routing one step ahead so the SSD fetch overlaps compute. Together they are 0.9% of the file.</p><button class="outline-btn full-width" onClick=${()=>{this.select(\'aligner\');this.patch({tab:\'inspect\'});}}>Open the prerouter heads</button><//>'),
 ("Three distinctions worth keeping",
  ' <${Section} title="Three distinctions worth keeping"><div class="layer-story"><h3>Stored is not active.</h3><p>Eight of 256 experts are chosen per token, but all 256 remain in the checkpoint. Illumination changes, volume does not — and the under-3-GiB claim is about the active set, not the file.</p><h3>A fused bank is not a per-expert file.</h3><p>BF16 writes experts as one fused tensor per layer; FP8 writes them one by one. The same parameters, 1,045 tensors against 64,196 — bookkeeping, not architecture.</p><h3>A quantizer ignores more than it converts.</h3><p>The int4 build keeps 80 router modules at 8-bit on purpose and drops the vision tower entirely. Read the config and the ignore list before believing a compression ratio.</p></div><//>'),
 # ---------- storage ----------
 ("Why NVFP4 grows here",
  ' <${Section} title="Three precisions, one architecture"><div class="equation"><span>BF16</span><code>2 B / parameter</code><span>FP8</span><code>1 B + block scales</code><span>INT4 g64</span><code>0.5 B + scales and biases</code></div><${Fact} label="FP8 saves" value=${bytes(FP8_DELTA,s.binary)} color=${COL.dec}/><${Fact} label="Edge0 int4 saves" value=${bytes(E0_DELTA,s.binary)} color=${COL.expert}/><p class="fine">The edge build is smaller than a clean 4× would suggest, for reasons that are visible in the file: experts are packed at 4 bits, but the 80 router modules stay at 8-bit, the norms stay BF16, and the LoRA and prerouter adapters are added on top rather than replacing anything.</p><//>'),
 ("Accounting assumptions and limits",
  ' <details class="assumptions"><summary>Accounting assumptions and limits</summary><p>Tensor payload only: shard headers, file padding and exporter metadata are excluded, so these are not download sizes.</p><p>Per-expert tensors are folded into the fused banks the BF16 base stores, and quantization scales and biases (weight_scale_inv, scales, biases) are folded into their owner. That is why all three modes show the same logical tensor list even though the FP8 repo has 64,196 tensors and the base has 1,045.</p><p>The FP8 checkpoint also ships one MTP layer (mtp.layers.0, 0.8537 GB) that the BF16 base and the edge build do not have. It is shown as its own module rather than hidden inside a rounding error. Active memory, SSD bandwidth and throughput are runtime quantities and are not modelled here.</p></details></div>`;}'),
 # ---------- cache view ----------
 ("COMPRESSED SPARSE ATTENTION 2",
  ' renderCache(){const s=this.state,n=s.context,linear=KV_LINEAR_STATE,full=n*KV_FULL_PER_TOKEN;return html`<div><div class="inspect-path">CONTEXT COST / TWO KINDS OF MEMORY</div><h2 class="editorial">Thirty constant.<br/><em>Ten that grow.</em></h2><p class="lede">The gated-linear layers carry a fixed recurrent state; only the ten full-attention layers keep a KV cache.</p><div class="storage-total cache-total"><small>FULL-ATTENTION CACHE / TOKEN</small><strong>20,480 <em>bytes</em></strong><span>10 layers × 2 KV heads × 256 dims × 2 tensors × 2 bytes</span></div>'),
 ('title="Stretch the context" tag="UP TO 1,048,576"',
  ' <${Section} title="Stretch the context" tag="UP TO 262,144"><label class="range-title" for="context-number">Context tokens <input id="context-number" type="number" min="128" max="262144" step="128" value=${n} onChange=${e=>{const v=Number(e.target.value);this.patch({context:clamp(Number.isFinite(v)?Math.round(v):128,128,262144)});}}/></label><input class="slider" aria-label="Context length logarithmic slider" type="range" min="7" max="18" step="0.05" value=${Math.log2(n)} onInput=${e=>this.patch({context:clamp(Math.round(2**Number(e.target.value)),128,262144)})}/><div class="range-ends"><span>128</span><span>8K</span><span>256K</span></div><div class="preset-row">${[16384,65536,131072,262144].map(v=>html`<button class=${n===v?\'active\':\'\'} onClick=${()=>this.patch({context:v})}>${v===262144?\'256K\':v/1024+\'K\'}</button>`)}</div><${Fact} label="Full-attention KV" value=${bytes(full,s.binary)} color=${COL.full}/><${Fact} label="Recurrent state (fixed)" value=${bytes(linear,s.binary)} color=${COL.swa}/><p class="fine">The recurrent figure does not depend on the context: 30 layers × 32 value heads × 128 × 128 keys at two bytes. Long prompts cost the linear layers nothing extra.</p><//>'),
 ("Where 890 comes from",
  ' <${Section} title="Where these numbers come from"><div class="equation"><span>FULL LAYER / TOKEN</span><code>(2 × 256) × 2 × 2 B = 2,048 B</code><span>ALL TEN / TOKEN</span><code>2,048 × 10 = 20,480 B</code><span>RECURRENT / LAYER</span><code>32 × 128 × 128 × 2 B = 1.05 MB</code></div><p class="fine">BF16 arithmetic from the published shapes. The full-attention cache is what an SSD-offloaded runtime has to keep in RAM; the recurrent states are what it keeps instead of a KV cache in the other thirty layers.</p><//>'),
 ("Hierarchical sparse indexer",
  ' <${Section} title="What the int4 build actually costs" tag="GROUP 64"><${Fact} label="Packed weights" value="0.5 B / parameter"/><${Fact} label="Scales + biases" value="~0.031 B / parameter"/><${Fact} label="8-bit overrides" value="80 router modules"/><${Fact} label="Vision tower" value="dropped in this build"/><${Fact} label="Adapters" value="180.7 MB on top"/><p class="fine">Affine 4-bit stores one scale and one bias per group of 64 values, so a packed row costs 0.5 B plus 4 bytes per 64 weights. The measured 19.6895 GB includes the two adapter files; the four model shards alone are smaller.</p><//><${Note} color=${COL.full}>KV and state figures are arithmetic from the published config, not measured device memory. The runtime also holds activations, the active expert set and the SSD staging buffers — none of which are checkpoint bytes.<//></div>`;}'),
 # ---------- benchmarks ----------
 ("REPORTED EVALUATIONS / NATIVE MODEL",
  ' renderBench(){const s=this.state,b=BENCH[s.bench];return html`<div><div class="inspect-path">PUBLISHER-REPORTED LEADERBOARD / AS PUBLISHED</div><h2 class="editorial">Capability,<br/><em>with context.</em></h2><p class="lede">Scores collected from each model\\u2019s own card by the original atlas page. This page measures bytes and claims no scores of its own; Edge0-35B-A3B is not in that publisher set; its own card figure is added as the first row wherever the card reports the same benchmark, and a blank cell means the card does not publish it.</p><label class="field-label">Compare a benchmark<select value=${s.bench} onChange=${e=>this.patch({bench:Number(e.target.value)})}>${BENCH.map((r,i)=>html`<option value=${i}>${r[0]}</option>`)}</select></label><div class="benchmark-chart">${BENCH_MODELS.map((name,i)=>html`<div class=${\'benchmark-row\'}><div><span>${name}</span><b>${b[2][i]===null?\'Not reported\':b[2][i].toFixed(1)}</b></div><div class="bench-track"><i style=${{width:(b[2][i]||0)+\'%\',background:COL.enc,opacity:1}}/></div></div>`)}</div><p class="fine">${b[0]} / ${b[1]}. Percentages or the card\'s 0-100 score; ZeroBench uses Pass@5, ProgramBench Almost@1, DeepSWE resolved rate. Do not average unlike metrics.</p><div class="card-bench"><div class="inspect-path">PUBLISHER CARD / THIS CHECKPOINT</div><p class="card-lede">Every benchmark this checkpoint&rsquo;s own card reports, with the card&rsquo;s own comparison columns, reproduced unchanged. Where a row in the series chart above reads &ldquo;Not reported&rdquo;, the card does not publish that benchmark.</p><div class="card-scroll"><table class="card-table"><thead><tr>${CARD_BENCH.headers.map(h=>html`<th>${h}</th>`)}</tr></thead><tbody>${CARD_BENCH.rows.map(r=>r[0].startsWith("== ")?html`<tr class="sec"><td colSpan=${CARD_BENCH.headers.length}>${r[0].slice(3)}</td></tr>`:html`<tr>${r.map((c,i)=>html`<td class=${i===0?"lbl":(i===1?"num own":"num")}>${c}</td>`)}</tr>`)}</tbody></table></div><p class="fine">Source: <a href="https://huggingface.co/${CARD_BENCH.src}" target="_blank" rel="noopener">${CARD_BENCH.src}</a> model card, retrieved 2026-09-15. Values are the publisher&rsquo;s; this page measures bytes and adds no numbers.</p></div>'),
 ("Evaluation conditions",
  ' <${Section} title="Evaluation conditions"><${Fact} label="Quantization" value="MLX affine int4 / group 64"/><${Fact} label="8-bit overrides" value="mlp.gate + shared_expert_gate"/><${Fact} label="Adapters" value="Recover-LoRA, distillation"/><${Fact} label="Runtime" value="edge0 streaming, under 3 GiB"/><p class="fine">The vision row only applies to the base checkpoints: the edge preview has no vision tower, so a text-only build cannot be scored on image benchmarks. Harnesses and protocols differ per benchmark; see the card.</p><${Note} color=${COL.expert}>Publisher-reported scores. This page measures bytes; it does not evaluate the int4 build, and no quality equivalence is claimed for FP8.<//><//>'),
 ("Reasoning is an API setting",
  ' <${Section} title="What the edge build trades away"><label class="range-title">parameters kept at fp16 <output>${(100-s.effort*.8).toFixed(0)}%</output></label><input class="slider" type="range" min="1" max="100" value=${s.effort} aria-label="Illustrative precision trade-off" onInput=${e=>this.patch({effort:Number(e.target.value)})}/><pre class="small-code">${JSON.stringify({base_bits:4,group_size:64,overrides_8bit:80,adapters_MB:180.7},null,2)}</pre><p class="fine">A slider that only illustrates the trade-off: routers stay at 8 bits because routing is discrete, adapters carry the correction, and the vision tower was removed rather than compressed.</p><//></div>`;}'),
 # ---------- sources ----------
 ("PROVENANCE / SEPTEMBER 10, 2026",
  ' renderSources(){return html`<div><div class="inspect-path">PROVENANCE / MEASURED FROM PUBLISHED SHARDS</div><h2 class="editorial">Trace every<br/><em>assumption.</em></h2><p class="lede">The card supplies the claims. The configs supply the shapes. The shard headers supply the bytes — all three modes here were read over HTTP Range, not estimated.</p><div class="source-status"><i/> Offline app / no runtime requests</div>'),
 ("The supplied NVFP4 recipe",
  ' <${Section} title="What each repository actually contains"><p class="fine">The BF16 base writes 256 experts as one fused bank per layer, ships an untied 248,320-row head and includes the vision tower. The FP8 build writes experts per expert, carries per-block weight_scale_inv tensors (64,196 tensors total) and adds one MTP layer the base does not have. The edge preview has four model shards, no vision tensors, and two separate adapter files.</p><${Fact} label="BF16 base" value="71.9036 GB / 26 shards"/><${Fact} label="FP8 build" value="37.4548 GB / 42 shards"/><${Fact} label="Edge0 int4" value="19.6895 GB / 6 files"/><${Fact} label="MTP layer" value="0.8537 GB / FP8 only"/><//>'),
 ("Tower, split and execution",
  ' <${Section} title="Tower, split and the three modes"><p class="fine">The tower is a logical layer-order view, not a map of safetensors byte offsets. Splitting moves the same 40 objects into two reading groups; it does not create a second stack, and both layouts use the exact same tensor inventory.</p><p class="fine">The animation walks Route → Fetch → Compute → Decode → Adapt: routing, the SSD expert fetch, the forward pass itself, the decode cadence reported by the card, and the adapter that corrects the 4-bit weights. Nothing here executes a model, and no throughput is simulated.</p><p class="fine">Training mode illustrates the Recover-LoRA recipe in outline — frozen int4 student, FP teacher, gradients to the adapters only. It is a schematic, not the authors\u2019 training code.</p><//>'),
 ("Interpretation rules",
  ' <${Section} title="Interpretation rules"><p class="fine">35B parameters with 3B active per token and the under-3-GiB memory figure are the publisher\u2019s claims. The measured total here is ${fmtP(TOTAL_P)} stored logical values across 1,045 base tensors — audited tensor by tensor from the shard headers of the three repositories.</p><p class="fine">Routing, fetch, compute and adapter animations are explanatory. No inference runs. The timeline is not a latency chart and no weight data is bundled in this HTML.</p><p class="fine">Volumes, not footprint areas: unfolding experts conserves modelled mass, and zooming never alters the byte scale. KV and recurrent-state figures are arithmetic from published shapes, not measured device memory.</p><//>'),
 # ---------- modals and chrome ----------
 ("DEEPSEEK MODEL ATLAS",
  ' renderModal(){const s=this.state;if(!s.modal)return null;let title={help:\'Explore the model\',config:\'Embedded configurations\',audit:\'Safetensors header audit\',credits:\'Credits & licenses\'}[s.modal];return html`<div class="modal-backdrop" onClick=${e=>{if(e.target===e.currentTarget)this.patch({modal:null});}}><div class=${\'modal \'+(s.modal===\'config\'?\'wide\':\'\')} role="dialog" aria-modal="true" aria-label=${title}><div class="modal-head"><div><div class="eyebrow">EDGE0 MODEL ATLAS</div><h2>${title}</h2></div><button class="icon-button" aria-label="Close dialog" onClick=${()=>this.patch({modal:null})}><${Icon} name="close"/></button></div><div class="modal-body">'),
 ("['P','Cycle native / NVFP4 / BF16']",
  ' ${s.modal===\'help\'&&html`<p class="lede">A file to keep, inspect and share. Everything needed to render the atlas is embedded.</p><div class="help-grid">${[[\'V\',\'Merge tower / separate the two reading groups\'],[\'B / T\',\'Hide inspector / animation panel\'],[\'+ / -\',\'Increase / decrease all text\'],[\'Blank panel background\',\'Click the arrow cursor to collapse; text is protected\'],[\'Drag\',\'Orbit the model\'],[\'Right-drag / Shift-drag\',\'Pan in camera space\'],[\'Wheel / pinch\',\'Zoom without changing scale\'],[\'Click a layer\',\'Open named weight tensors\'],[\'Click a labeled weight\',\'Pin its role, shape and bytes\'],[\'F / X\',\'Columns or floor / banks or experts\'],[\'[ / ]\',"Walk the layer\\u2019s tensor list"],[\'Click an expert\',\'Split its gate-up and down bank\'],[\'Two-finger drag\',\'Pan on touch screens\'],[\'R / double-click\',\'Reset the camera\'],[\'P\',\'Cycle BF16 / FP8 / Edge0 int4\'],[\'Space\',\'Pause or resume the story\'],[\'Up / Down\',\'Previous or next module\'],[\'L / K\',\'Toggle labels / flow paths\'],[\'1 / 2 / 3\',\'Architecture / Storage / Context\']].map(([k,v])=>html`<div><kbd>${k}</kbd><span>${v}</span></div>`)}</div><${Note}>The animation starts in Compute and loops that phase. Choose another phase or turn off Loop phase to play the whole story. Tower order is not disk order; Split moves the same objects. Training mode illustrates the distillation recipe, not a second checkpoint. Routing is synthetic. Solids represent measured stored bytes, not device utilization, FLOPs or measured throughput.<//><button class="outline-btn full-width" onClick=${()=>this.patch({modal:\'audit\'})}>Check exact bytes from local checkpoint headers</button>`}'),
 ("Full supplied fields.",
  ' ${s.modal===\'config\'&&html`<div class="config-switch">${[\'bf16\',\'fp8\',\'edge0\'].map(m=>html`<button class=${(s.configMode||\'bf16\')===m?\'active\':\'\'} onClick=${()=>this.patch({configMode:m})}>${m===\'bf16\'?\'Qwen3.6 base\':m===\'fp8\'?\'Qwen3.6 FP8\':\'Edge0 int4\'}</button>`)}</div><p class="fine">The released configs, embedded field for field. The Edge0 tab includes its MLX quantization block and the 80 per-module 8-bit overrides; the FP8 tab includes Qwen\u2019s fp8 recipe.</p><pre class="config-code">${JSON.stringify(s.configMode===\'edge0\'?E0_CONFIG:s.configMode===\'fp8\'?FP8_CONFIG:CFG,null,2)}</pre><button class="outline-btn" onClick=${()=>safeDownload((s.configMode||\'bf16\')+\'-config.json\',JSON.stringify(s.configMode===\'edge0\'?E0_CONFIG:s.configMode===\'fp8\'?FP8_CONFIG:CFG,null,2))}><${Icon} name="download" size=${16}/> Save config.json</button>`}'),
 ("DSpark draft stages",
  ' <div class="workspace"><nav class="layer-rail" aria-label="Model modules"><button class=${\'rail-special\'+(s.selected===\'D0\'?\' selected\':\'\')} title="MTP layer (FP8 build only)" onClick=${()=>{this.patch({view:\'architecture\'});this.select(\'D0\');}}>D</button><div class="rail-caption">OUT</div><div class="rail-layers">${[...LAYERS].reverse().map(m=>html`<button key=${m.id} aria-label=${m.label+\' \'+m.mode} class=${\'rail-layer \'+(s.selected===m.id?\'selected\':\'\')} style=${{ \'--layer-color\':COL[m.mode]}} onClick=${()=>{if(s.view!==\'architecture\')this.patch({view:\'architecture\'});this.select(m.id);}} title=${m.label+\' / \'+m.mode+\' / \'+m.part}><span>${String(m.index).padStart(2,\'0\')}</span><i/></button>`)}</div><div class="rail-caption">IN</div><button class=${\'rail-special\'+(s.selected===\'vision\'?\' selected\':\'\')} title="Vision tower" onClick=${()=>{this.patch({view:\'architecture\'});this.select(\'vision\');}}>V</button></nav>'),
 ("global KV payload",
  ' <div class="scene-scale"><span class="scale-glyph"/><span>1 cubic unit = 1 GB <em>${s.view===\'cache\'?\'context memory arithmetic\':\'audited weight payload\'} / ${this.engine&&this.engine.renderer.software?\'CPU 3D\':\'WebGL2\'}</em></span></div><div class="scene-legend">${(s.view===\'cache\'?[[\'full\',\'Full attn KV\'],[\'swa\',\'Recurrent state\']]:s.view===\'storage\'?[[\'expert\',\'Experts\'],[\'lora\',\'LoRA\'],[\'prerouter\',\'Prerouter\']]:[[\'full\',\'Full attention\'],[\'swa\',\'Gated linear\']]).map(([key,l])=>html`<span><i style=${{background:COL[key]}}/>${l}</span>`)}</div>'),
 ("DSPARK / FIVE-TOKEN DRAFT",
  ' ${s.view===\'architecture\'&&s.activity===\'inference\'&&(phaseI===1||s.selected===\'D0\')&&html`<div class="draft-diagram"><div><b>EXPERT FETCH / 8 OF 256</b><small>The prerouter guesses the next layer, so the fetch overlaps compute</small></div><div class="draft-cells">${[.98,.94,.87,.62,.41].map((confidence,i)=>{let step=(s.time>=6?s.time-6:2),stage=step<1.2?\'predict\':step<2.8?\'fetch\':i<3?\'resident\':i===3?\'arriving\':\'queued\';return html`<div class=${"draft-cell "+stage}><small>expert ${i*7+3}</small><b>${step<1.2?\'...\':confidence.toFixed(2)}</b><span>${stage}</span></div>`;})}</div><p>Routing is synthetic; this shows fetch states, not weight volumes.</p></div>`}'),
 ("function fontPreference(){",
  'function fontPreference(){try{const n=Number(localStorage.getItem(\'edge0-atlas-font\'));return Number.isFinite(n)&&n>=.85&&n<=1.5?n:1;}catch(_){return 1;}}'),
 ("componentDidUpdate(prevProps,prevState)",
  ' componentDidUpdate(prevProps,prevState){if(prevState&&prevState.fontScale!==this.state.fontScale){try{localStorage.setItem(\'edge0-atlas-font\',String(this.state.fontScale));}catch(_){}}if(this.engine)this.engine.sync(this.state);if(prevState&&(prevState.selected!==this.state.selected||prevState.view!==this.state.view||prevState.tab!==this.state.tab)&&this.panelRef.current)this.panelRef.current.scrollTop=0;if(prevState&&prevState.modal!==this.state.modal){if(this.state.modal){this.modalReturnFocus=document.activeElement;setTimeout(()=>document.querySelector(\'.modal-head button\')?.focus(),0);}else if(this.modalReturnFocus&&document.contains(this.modalReturnFocus))this.modalReturnFocus.focus({preventScroll:true});}}'),
 ("deepseek-v41-'+mode+'-derived-ledger.json'",
  ' exportLedger(){let mode=this.state.precision;safeDownload(\'edge0-35b-\'+mode+\'-ledger.json\',JSON.stringify({title:\'Edge0 35B A3B - measured safetensors payload ledger\',date:\'2026-09-14\',precision:mode,status:\'MEASURED FROM PUBLISHED SHARD HEADERS\',notes:[\'Tensor payload only. File padding, headers, exporter metadata and unknown buffers are excluded.\',\'Per-expert tensors are folded into the fused banks of the BF16 base; quantization scales and biases are folded into their owner.\',\'KV cache and recurrent-state figures shown in the context view are arithmetic from published shapes, not device memory.\'],bytes:TOTALS[mode],logicalParameters:TOTAL_P,modules:MODULES.map(m=>({id:m.id,label:m.label,bytes:sumB(m.ws,mode),parameters:sumP(m.ws),weights:m.ws.map(w=>({...w,storageBytes:wBytes(w,mode),displayFormat:wFormat(w,mode)}))})),sources:SOURCES},null,2));this.notify(\'Byte ledger exported. Every figure is measured from published shard headers.\');}'),
 ("deepseek-v41-3d-",
  ' snapshot(){if(!this.engine)return;const a=document.createElement(\'a\');a.href=this.engine.snapshot();a.download=\'edge0-35b-3d-\'+this.state.view+\'.png\';a.click();this.notify(\'3D canvas saved. Interface labels are not part of the canvas.\');}'),
 ("['native','nvfp4','bf16']",
  ' key(e){if(e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toLowerCase();if(k===\'escape\'){if(this.state.modal||this.state.sheet)this.patch({modal:null,sheet:false});else if(this.state.tensor||this.state.expert!==null)this.patch({tensor:null,hoverTensor:null,expert:null});else this.patch({selected:null});return;}if(this.state.modal){if(k===\'tab\'){let nodes=[...document.querySelectorAll(\'.modal button:not(:disabled),.modal a,.modal input:not([hidden]),.modal select,.modal summary\')].filter(x=>x.getClientRects().length),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(/input|select|textarea/i.test(e.target.tagName)||e.target.tagName===\'BUTTON\'&&k===\' \')return;if(k===\' \'){e.preventDefault();this.patch({playing:!this.state.playing});}if(k===\'arrowdown\'){e.preventDefault();this.walk(1);}if(k===\'arrowup\'){e.preventDefault();this.walk(-1);}if(k===\'+\'||k===\'=\'){e.preventDefault();this.changeFont(.1);}if(k===\'-\'){e.preventDefault();this.changeFont(-.1);}if(k===\'b\')this.togglePanel();if(k===\'t\')this.patch({timelineHidden:!this.state.timelineHidden});if(k===\'v\')this.setLayout(this.state.layout===\'tower\'?\'split\':\'tower\');if(k===\'r\'&&this.engine){if(this.state.selected)this.engine.focus(this.state.selected);else this.engine.reset();}if(k===\'f\')this.patch({detailLayout:this.state.detailLayout===\'floor\'?\'column\':\'floor\'});if(k===\'x\')this.patch({expertView:!this.state.expertView,expert:null});if(k===\'[\')this.walkTensor(-1);if(k===\']\')this.walkTensor(1);if(k===\'p\'){let keys=MODE_KEYS;this.patch({precision:keys[(keys.indexOf(this.state.precision)+1)%keys.length]});}if(k===\'l\')this.patch({labels:!this.state.labels});if(k===\'k\')this.patch({links:!this.state.links});if([\'1\',\'2\',\'3\'].includes(k))this.setView([\'architecture\',\'storage\',\'cache\'][Number(k)-1]);}'),
 # ---------- engine functions that must name this model ----------
 ("function moduleExplanation(m){",
  ' function moduleExplanation(m){if(!m)return EXP.overview;if(m.mode)return EXP[m.mode];if(m.id===\'vision\')return EXP.vision;if(m.id===\'adapters\'||m.id===\'aligner\')return EXP.selfcond;if(m.id===\'embed\')return {title:\'Token embedding.\',body:\'[248,320, 2048] — 1.0 GB at BF16 and untied from the output head, so both tables exist on disk. The int4 build packs each with group-64 scales and biases.\'};if(m.id===\'head\')return {title:\'Output head, untied.\',body:\'2048 → 248,320 logits: its own 1.0 GB at BF16, separate from the embedding. In the FP8 build it stays in the original precision; in the edge build it is packed like everything else.\'};if(m.id===\'D0\')return {title:\'MTP layer.\',body:\'One multi-token-prediction block that the FP8 repository ships and neither the BF16 base nor the edge build has: mtp.layers.0 plus mtp.fc, 0.8537 GB. Shown as its own module instead of being hidden in a rounding error.\'};return EXP.overview;}'),
 ("function describeFormat(w){",
  ' function describeFormat(w){return w.note||({bf16:\'Two bytes per logical value in the Qwen3.6-35B-A3B base.\',fp8:\'e4m3 weights with a per-block weight_scale_inv tensor in the Qwen FP8 build.\',edge0:\'MLX affine int4: packed U32 words with one scale and one bias per group of 64 values.\'}[w.format]||\'See the embedded configurations in Sources.\');}'),
 ("function resolveAuditModule(name){",
  ' function resolveAuditModule(name){let n=name.replace(/^(?:language_model\\.|model\\.)+/,\'\');let a=n.match(/^layers\\.(\\d+)\\./);if(a)return (+a[1])<40?\'L\'+a[1]:\'D\';if(/^mtp\\./.test(n))return \'D0\';if(/^model\\.language_model\\.layers|^language_model\\.model\\.layers/.test(n)){let b=n.match(/^.*?layers\\.(\\d+)\\./);if(b)return \'L\'+b[1];}a=name.match(/lora::/)||/lora_([AB])$/.test(name);if(a)return \'adapters\';if(/^prerouter|^layers\\.\\d+\\.(fc1|fc2|linear_init)/.test(n)||/prerouter_/.test(name))return \'aligner\';if(/^(model\\.)?visual|^visual\\./.test(n))return \'vision\';if(/embed_tokens/.test(n))return \'embed\';if(/^(model\\.)?language_model\\.norm|^norm\\.|lm_head/.test(n))return \'head\';return \'Unmapped\';}'),
]
